        An unknown id, another tenant's operation, or another operator's
        operation all answer None so existence never leaks.
        """
        record = self._read_op(operation_id)
        if record is None:
            return None
        if record.tenant_id != tenant_id or record.operator != operator:
            return None
        return record

    # -- crash recovery ----------------------------------------------------
    def recover_pending(self) -> None:
        """Finalize leftover pending operations after a restart.

        The key/outbox stores have already resolved pending markers and
        reaped handles keyed by the same ids (operation_id == event_id ==
        journal id). A pinned event in the ledger therefore decides the
        outcome: a success event commits the operation (response rebuilt
        from durable state); a staged rejection finalizes with its stored
        status. With no event the operation never committed; it stays
        pending, and the next same-binding live request re-executes it.
        """
        try:
            names = os.listdir(self.dir_path)
        except OSError:
            return
        for name in names:
            if not name.endswith(".json"):
                continue
            operation_id = name[:-5]
            record = self._read_op(operation_id)
            if record is None or record.status != STATUS_PENDING:
                continue
            try:
                self._finalize_committed(record)
            except LedgerError:
                # The ledger cannot be read right now; leave it pending for a
                # later open or a live same-binding request to resolve.
                continue

